// Canonical source: src/functions/f2/readiness.mjs#evaluateModuleReadiness
function result(status, ready, blockers = []) { return { status, ready, blockers }; }
function evaluateModuleReadiness(moduleCode, context = {}) {
  switch (moduleCode) {
    case "delivery":
      return context.linkSent === true && context.confirmationPolicySatisfied === true
        ? result("completed", true)
        : result("in_progress", false, ["DELIVERY_POLICY_INCOMPLETE"]);
    case "post_sale":
      return context.actionsCompletedOrSkipped === true
        ? result("completed", true)
        : result("in_progress", false, ["POST_SALE_INCOMPLETE"]);
    default:
      return result("blocked", false, ["UNKNOWN_MODULE_CODE:" + moduleCode]);
  }
}
return {json:evaluateModuleReadiness("post_sale",{
  actionsCompletedOrSkipped:Boolean($json.actions_completed_or_skipped ?? $json.actionsCompletedOrSkipped)
})};

const readiness=$json;
const input=$('Receive Post-sale Context').item.json;
const trigger=String(input.trigger_type ?? '');
const eventId=input.customer_event_id;
const consent=input.publication_consent ?? null;

if(trigger==='delivery_link_sent'){
  return {json:{
    status:'planned_shadow',
    readiness,
    operations:[
      {action:'UPSERT_MODULE_STATE',customer_event_id:eventId,module_code:'post_sale',status:'in_progress',ready:false},
      {action:'SCHEDULE_POST_SALE_ACTION',customer_event_id:eventId,action_type:'delivery_confirmation_check'}
    ],
    blockers:['SEND_DISABLED']
  }};
}

if(trigger==='delivery_confirmed'){
  if(input.delivery_status!=='confirmed'){
    return {json:{status:'blocked',readiness,operations:[],blockers:['DELIVERY_NOT_CONFIRMED']}};
  }
  return {json:{
    status:'planned_shadow',
    readiness,
    operations:[
      {action:'UPSERT_MODULE_STATE',customer_event_id:eventId,module_code:'post_sale',status:'in_progress',ready:false},
      {
        action:'REQUEST_RESPONSE_COMPOSITION',
        customer_event_id:eventId,
        response_action:'COMPOSE_REVIEW_REQUEST',
        review_url:'https://g.page/click-mais-photo-cabine?share'
      },
      {action:'EMIT_EVENT',event_type:'post_sale_review_candidate',customer_event_id:eventId}
    ],
    blockers:['SEND_DISABLED']
  }};
}

if(trigger==='publication_consent_received'){
  if(!consent || typeof consent.consent!=='boolean' || !consent.channel){
    return {json:{status:'blocked',readiness,operations:[],blockers:['PUBLICATION_CONSENT_INVALID']}};
  }
  const source=consent.source_type ?? 'customer';
  if(!['customer','human','contract','integration'].includes(source)){
    return {json:{status:'blocked',readiness,operations:[],blockers:['PUBLICATION_CONSENT_SOURCE_INVALID']}};
  }
  const operations=[
    {
      action:'UPSERT_PUBLICATION_CONSENT',
      customer_event_id:eventId,
      channel:consent.channel,
      consent:consent.consent,
      source_type:source,
      source_ref:consent.source_ref ?? null
    },
    {
      action:'EMIT_EVENT',
      event_type:consent.consent?'publication_consent_granted':'publication_consent_denied',
      customer_event_id:eventId,
      channel:consent.channel
    }
  ];
  if(consent.consent===false){
    operations.push({action:'SUPPRESS_PUBLICATION',customer_event_id:eventId,channel:consent.channel});
  }
  return {json:{
    status:consent.consent?'consent_recorded':'suppressed',
    readiness,
    operations,
    delivery_affected:false,
    blockers:[]
  }};
}

if(trigger==='publication_request'){
  if(!consent || consent.consent!==true || !consent.channel){
    return {json:{
      status:'denied',
      readiness,
      operations:[],
      delivery_affected:false,
      blockers:['PUBLICATION_CONSENT_REQUIRED']
    }};
  }
  return {json:{
    status:'adapter_required',
    readiness,
    operations:[
      {
        action:'REQUEST_AUTHORIZED_PUBLICATION_ADAPTER',
        customer_event_id:eventId,
        channel:consent.channel,
        consent_source_ref:consent.source_ref ?? null
      }
    ],
    delivery_affected:false,
    blockers:['PUBLICATION_ADAPTER_NOT_CONNECTED']
  }};
}

if(trigger==='post_sale_complete'){
  if(!readiness.ready){
    return {json:{status:'blocked',readiness,operations:[],blockers:readiness.blockers}};
  }
  return {json:{
    status:'completed',
    readiness,
    operations:[
      {action:'UPSERT_MODULE_STATE',customer_event_id:eventId,module_code:'post_sale',status:'completed',ready:true,blockers:[]},
      {action:'EMIT_EVENT',event_type:'post_sale_completed',customer_event_id:eventId}
    ],
    blockers:[]
  }};
}

return {json:{status:'blocked',readiness,operations:[],blockers:['POST_SALE_TRIGGER_UNKNOWN']}};
